-    fn select_in_domain(
-        &mut self,
-        domain: &CandidateDomain,
-        affinity_lookup_enabled: bool,
-        affinity_assignment_enabled: bool,
-        allow_capacity_fallback: bool,
-    ) -> Option<Arc<Worker>> {
